import{_ as t,o,c as a,ag as r}from"./chunks/framework.Cyu1VozZ.js";const m=JSON.parse('{"title":"Import & Export","description":"","frontmatter":{},"headers":[],"relativePath":"guide/import-export.md","filePath":"guide/import-export.md"}'),d={name:"guide/import-export.md"};function i(s,e,n,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="import-export" tabindex="-1">Import &amp; Export <a class="header-anchor" href="#import-export" aria-label="Permalink to &quot;Import &amp; Export&quot;">​</a></h1><p>Wafflebase reads and writes the file formats your team already uses, so you can bring existing work in and take finished work out. Nothing is locked to the platform.</p><h2 id="at-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Product</th><th>Import</th><th>Export</th></tr></thead><tbody><tr><td><strong>Sheets</strong></td><td>Excel (<code>.xlsx</code>), CSV/TSV, JSON/JSONL, Parquet</td><td>— <em>(CSV/JSON via <a href="./../developers/cli.html">CLI</a>)</em></td></tr><tr><td><strong>Docs</strong></td><td>Word (<code>.docx</code>)</td><td>Word (<code>.docx</code>), PDF (<code>.pdf</code>), Markdown (<code>.md</code>), plain text (<code>.txt</code>)</td></tr><tr><td><strong>Slides</strong></td><td>PowerPoint (<code>.pptx</code>)</td><td>PowerPoint (<code>.pptx</code>), PDF (<code>.pdf</code>)</td></tr><tr><td><strong>Notes</strong></td><td>— <em>(Markdown via <a href="./../developers/cli.html">CLI</a>)</em></td><td>— <em>(Markdown via <a href="./../developers/cli.html">CLI</a>)</em></td></tr><tr><td><strong>Board</strong></td><td>Miro board <em>(via <strong>Import from Miro…</strong>)</em></td><td>—</td></tr><tr><td><strong>PDF</strong></td><td>Upload (<code>.pdf</code>)</td><td>— <em>(view-only)</em></td></tr></tbody></table><p>Import always creates a <strong>new</strong> document; it never overwrites an open one. Export downloads a file from the document you are editing. Notes have no in-app import or export — a note&#39;s content <em>is</em> its Markdown, and it moves in and out through <code>wafflebase notes import</code> / <code>notes export</code>.</p><h2 id="importing-files" tabindex="-1">Importing files <a class="header-anchor" href="#importing-files" aria-label="Permalink to &quot;Importing files&quot;">​</a></h2><p>There is one entry for every format. From your workspace, open the <strong>New</strong> menu and choose <strong>Upload files…</strong>, or drag files straight onto the documents list. You can select several at once; each file is read and turned into the matching document type based on its extension:</p><table tabindex="0"><thead><tr><th>You upload</th><th>You get</th></tr></thead><tbody><tr><td><code>.xlsx</code></td><td>A spreadsheet — each sheet in the workbook becomes a tab. Values, formulas, and basic cell formatting are brought across.</td></tr><tr><td><code>.csv</code>, <code>.tsv</code>, <code>.json</code>, <code>.jsonl</code>, <code>.ndjson</code>, <code>.parquet</code></td><td>A spreadsheet with a single tab holding the parsed rows.</td></tr><tr><td><code>.docx</code></td><td>A document, mapping paragraphs, headings, lists, tables, and inline formatting into the editor.</td></tr><tr><td><code>.pptx</code></td><td>A deck: slides, text boxes, shapes, images, tables, and theme colors become native Wafflebase elements.</td></tr><tr><td><code>.pdf</code></td><td>A PDF document you can read and comment on. The file is kept intact and viewed as-is rather than converted — see <a href="./../pdf/viewing-pdfs.html">Viewing PDFs</a>.</td></tr><tr><td><code>.png</code>, <code>.jpg</code>, <code>.jpeg</code>, <code>.gif</code>, <code>.webp</code></td><td>An image document you can view and download again — see <a href="./../pdf/viewing-images.html">Viewing Images</a>.</td></tr><tr><td>anything else</td><td>A stored file with no preview, which you can download again from its header.</td></tr></tbody></table><p>A panel in the bottom-right corner shows per-file progress while each file is parsed and any embedded images are uploaded into your workspace. An uploaded file is capped at <strong>50 MB</strong>, and an image document at <strong>25 MB</strong>. Images lifted <em>out</em> of a <code>.docx</code> or <code>.pptx</code> are a separate limit — they go to the workspace image store, which accepts <strong>10 MB</strong> per image.</p><p>A very large <code>.csv</code> or <code>.tsv</code> usually stops at an import budget (40,000 cells, plus an overall size ceiling) rather than failing: the sheet is created from the rows that arrived, and a toast on the documents list says how many were kept. The exception is a file whose very first row already busts a budget — there is nothing to truncate down to, so the import fails with an error instead.</p><p><code>.parquet</code> is held to the same 40,000-cell limit, but it is never truncated: the row and column counts are checked before anything is read and an over-limit file is rejected outright. <code>.xlsx</code>, <code>.json</code> and <code>.jsonl</code> have no cell budget.</p><p>The <strong>Import from Miro…</strong> entry in the same menu is separate — it reads a Miro board through Miro&#39;s API rather than a file on disk, and creates a <a href="./../board/using-the-board.html">board</a> from it.</p><h2 id="exporting-files" tabindex="-1">Exporting files <a class="header-anchor" href="#exporting-files" aria-label="Permalink to &quot;Exporting files&quot;">​</a></h2><h3 id="docs" tabindex="-1">Docs <a class="header-anchor" href="#docs" aria-label="Permalink to &quot;Docs&quot;">​</a></h3><p>In the document editor, open the <strong>Export</strong> menu (the download icon in the header) and choose:</p><ul><li><strong>Word (<code>.docx</code>)</strong> — the full document, including tables and headers/footers.</li><li><strong>PDF (<code>.pdf</code>)</strong> — a paginated, print-ready PDF that mirrors the on-screen page layout.</li><li><strong>Markdown (<code>.md</code>)</strong> — GitHub-Flavoured Markdown. Deliberately lossy: headings, lists, tables, links, images, bold, italic and strikethrough survive; alignment, indent, line spacing, colour, font choice and size, underline, super/subscript, merged and nested table cells, and headers/footers do not. Link and image targets are checked on the way out — anything that is not an ordinary web address (or, for an image, embedded image data) is dropped, leaving the text it wrapped behind.</li><li><strong>Plain text (<code>.txt</code>)</strong> — the text only, one block per line, with table rows tab-separated. All formatting is dropped.</li></ul><h3 id="slides" tabindex="-1">Slides <a class="header-anchor" href="#slides" aria-label="Permalink to &quot;Slides&quot;">​</a></h3><p>In the presentation editor, open the <strong>Export</strong> menu and choose:</p><ul><li><strong>PowerPoint (<code>.pptx</code>)</strong> — an editable deck with slides, shapes, text, images, tables, and the theme preserved as DrawingML.</li><li><strong>PDF (<code>.pdf</code>)</strong> — one slide per page, ready to share or print.</li></ul><h3 id="sheets" tabindex="-1">Sheets <a class="header-anchor" href="#sheets" aria-label="Permalink to &quot;Sheets&quot;">​</a></h3><p>Spreadsheets export to CSV or JSON through the <a href="./../developers/cli.html">command-line tool</a> (<code>wafflebase sheets …</code>). A built-in download menu in the grid editor is on the roadmap.</p><h2 id="fidelity-notes" tabindex="-1">Fidelity notes <a class="header-anchor" href="#fidelity-notes" aria-label="Permalink to &quot;Fidelity notes&quot;">​</a></h2><p>Wafflebase aims for a faithful round-trip, but the source formats are large and some constructs have no exact equivalent:</p><ul><li><strong>PPTX/DOCX import is best-effort.</strong> Common content — text, lists, tables, shapes, images, and theme colors — converts cleanly. Rare or application-specific features (embedded objects, macros, exotic effects) may be simplified or dropped.</li><li><strong>Fonts</strong> referenced by an imported file must be available in Wafflebase to render identically; otherwise a close fallback is substituted.</li><li><strong>Re-exporting</strong> a file you imported will not be byte-identical to the original, but preserves the structure and content faithfully.</li></ul><h2 id="automating-with-the-cli" tabindex="-1">Automating with the CLI <a class="header-anchor" href="#automating-with-the-cli" aria-label="Permalink to &quot;Automating with the CLI&quot;">​</a></h2><p>Every import/export path above is also scriptable. See the <a href="./../developers/cli.html">CLI reference</a> for <code>docs export</code>, <code>docs import</code>, <code>slides export</code>, <code>slides import</code>, <code>notes export</code>, <code>notes import</code>, and the <code>sheets</code> cell import/export commands — useful for batch conversions and pipelines.</p>',26)])])}const g=t(d,[["render",i]]);export{m as __pageData,g as default};
